#!/usr/bin/env node
/**
 * Start a LOCAL anvil fork of Base for VEYDARA's fork-only execution lab.
 *  - chain id 31337 (never 8453), so a fork signature can never be replayed on Base mainnet;
 *  - binds to 127.0.0.1 only;
 *  - accounts come from a fresh random mnemonic generated by anvil itself; their keys are written
 *    by anvil to a 0600 file OUTSIDE the repo (default /tmp/veydara-fork/anvil-accounts.json) and
 *    are never printed, logged or committed. They only ever hold fork balances.
 * Upstream: BASE_FORK_UPSTREAM or the public Base RPC (https://base-rpc.publicnode.com).
 */
import { spawn } from "node:child_process";
import { mkdirSync, chmodSync, existsSync } from "node:fs";
import { join } from "node:path";
import { homedir } from "node:os";

const upstream = process.env.BASE_FORK_UPSTREAM || "https://base-rpc.publicnode.com";
const port = process.env.FORK_PORT || "8545";
const dir = process.env.FORK_STATE_DIR || "/tmp/veydara-fork";
const accountsFile = join(dir, "anvil-accounts.json");
mkdirSync(dir, { recursive: true, mode: 0o700 });
const bin = [process.env.ANVIL_BIN, join(homedir(), ".foundry/bin/anvil"), "anvil"].find((b) => b && (b === "anvil" || existsSync(b)));
const args = ["--fork-url", upstream, "--chain-id", "31337", "--host", "127.0.0.1", "--port", port, "--mnemonic-random", "--accounts", "5", "--config-out", accountsFile, "--silent"];
if (process.env.FORK_BLOCK) args.push("--fork-block-number", process.env.FORK_BLOCK);
const child = spawn(bin, args, { stdio: ["ignore", "inherit", "inherit"] });
setTimeout(() => {
  try { chmodSync(accountsFile, 0o600); } catch { /* written once anvil is ready */ }
  console.log(`VEYDARA fork: anvil on http://127.0.0.1:${port} (chain 31337, forked from ${new URL(upstream).host}${process.env.FORK_BLOCK ? " @" + process.env.FORK_BLOCK : " @latest"}). Accounts file: ${accountsFile} (0600, not printed).`);
}, 4000);
child.on("exit", (c) => process.exit(c ?? 0));
for (const s of ["SIGINT", "SIGTERM"]) process.on(s, () => child.kill(s));
